<!--vbase-->
<template>
  <q-input
    class="accouting-input column inline full-width"
    outlined
    v-model="value"
    @update:model-value="
      (e: any) => {
        validateInput(e);
      }
    "
  >
  </q-input>

  <div>Combinations</div>

  <div v-for="(col, index) in combinations" :key="index">
    {{ col.range }}
    <div>
      {{ col.combinations }}
    </div>
    <br />
  </div>
  <div id="message"></div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import cache from 'src/utils/cache';
import { dynamicObj } from '../assets';
// Lazy-load range data (258 KB) only when component mounts
const range_data_loader = () => import('./Detail/utils/range.json');

export default defineComponent({
  el: '#app',
  mixins: [cache],
  props: {},
  components: {},
  data() {
    return {};
  },
  watch: {},
  async mounted() {
    const range_data = (await range_data_loader()).default;
    this.importJson(range_data);
    this.runTests();
  },
  methods: {
    importJson(data: dynamicObj) {
      for (const key in data) {
        if (data[key].AITF == data[key].AITT) {
          continue;
        }
        this.ranges.push({
          start: data[key].AITF,
          end: data[key].AITT,
        });
      }
    },
    runTests() {
      const testValues = [
        'prt-lsa',
        'prt-lsb',
        'prt-lsc',
        'prt-lsd', // should be true
        'P2-12345AB',
        'PRT-LSE',
        'PRT-LSE-A', // should be true
        'PRT-TC',
        'PRT-TF',
        'PRT-TCA', // should be true
        '920',
        '921',
        '922',
        '923',
        '919',
        '924',
        'ITPRT-HWOF',
        'ITPRT-TCOT',
        'ITPRT-HEOF', // should be true
        'ITPRT-KAOR',
        'ITPRT-LBOM',
        'ITPRT-HWOE',
        'ITPRT-TCOS',
        'PRT-LSD',
        'PRT-TB',
        '9199', // should be false
      ];

      const results = testValues.map((value) => {
        return `${value}: ${this.validateInput(value) ? 'Valid' : 'Invalid'}`;
      });

      const messageElement = document.getElementById('message') as HTMLElement;
      messageElement.innerHTML = results.join('<br>');

      const ranges = this.getRanges();

      try {
        this.combinations = [] as dynamicObj[];
        for (const range of ranges) {
          const dimenion_options = this.generateCombinations(range);

          this.combinations.push({
            range: range,
            combinations: dimenion_options,
          });
        }
      } catch (error) {
        // this.combinations = [];
        logError('Combination over load');
      }
    },

    generateCombinations(range: dynamicObj): dynamicObj[] {
      let combinations: dynamicObj[] = [];
      try {
        const start: string = range.start;
        const end: string = range.end;

        if (start.length !== end.length) {
          throw new Error('Combination over load');
        }

        const parts: string[][] = [];

        for (let i = 0; i < start.length; i++) {
          if (start[i] === end[i]) {
            parts.push([start[i]]);
          } else {
            const startCode: number = start.charCodeAt(i);
            const endCode: number = end.charCodeAt(i);
            const rangePart: string[] = [];

            if (startCode > endCode) {
              // Alphabetic range W-C , from W to Z and then from A to C
              for (let code = startCode; code <= 'Z'.charCodeAt(0); code++) {
                rangePart.push(String.fromCharCode(code));
              }
              for (let code = 'A'.charCodeAt(0); code <= endCode; code++) {
                rangePart.push(String.fromCharCode(code));
              }
            } else {
              for (let code = startCode; code <= endCode; code++) {
                rangePart.push(String.fromCharCode(code));
              }
            }

            parts.push(rangePart);
          }
        }

        this.combine('', parts, 0, combinations);
        return combinations;
      } catch (error) {
        throw new Error('Combination over load');
      }
    },

    combine(
      prefix: string,
      parts: string[][],
      index: number,
      combinations: dynamicObj[],
    ): void {
      if (combinations.length > 11) {
        throw new Error('Combination over load');
      }
      if (index === parts.length) {
        combinations.push({
          value: prefix,
          label: prefix,
        });
        // combinations.push(prefix);
        return;
      }

      for (let char of parts[index]) {
        this.combine(prefix + char, parts, index + 1, combinations);
      }
    },

    getRanges() {
      const ranges: dynamicObj[] = [
        {
          end: '2023-1',
          start: '2023-1',
        },
        {
          end: 'CLOUD23',
          start: 'CLOUD23',
        },
        {
          end: 'FIRE23',
          start: 'FIRE23',
        },
        {
          end: 'CLDCNVCST',
          start: 'CLDCNVCST',
        },
        {
          end: 'FIRERELATE',
          start: 'FIRERELATE',
        },
        {
          end: '2022-1',
          start: '2022-1',
        },
        {
          end: '2019-1',
          start: '2019-1',
        },
        {
          end: '2019-3',
          start: '2019-3',
        },
        {
          end: '2019.2',
          start: '2019-2',
        },
        {
          end: '2024',
          start: '2014',
        },
      ];
      // const ranges: dynamicObj[] = [
      // {
      //   start: '2019-2',
      //   end: '2019.2',
      // },
      //     {
      //         start: 'prt-lsa',
      //         end: 'prt-lsd'
      //     },
      //     {
      //         start: 'PRT-LSE',
      //         end: 'PRT-LSE'
      //     },
      //     {
      //         start: 'PRT-TC',
      //         end: 'PRT-TT'
      //     },
      //     {
      //         'start': '010',
      //         'end': '099'
      //     },
      //     {
      //         'start': 'P2',
      //         'end': 'PZZZZZZZZZ'
      //     },
      //     {
      //         start : 'ITPRT-HWOF',
      //         end : 'ITPRT-TCOT'
      //     },
      // ];
      return ranges;
    },

    validateInput(value: string) {
      const ranges = this.getRanges();

      let is_valid;
      for (const range of ranges) {
        if (value >= range.start && value <= range.end) {
          is_valid = true;
        }
      }

      // logInfo('validateInput', value, is_valid);
      return is_valid;
    },
  },
  setup() {
    return {
      ranges: ref([] as dynamicObj[]),
      value: ref(''),
      test_results: ref(''),
      combinations: ref([] as dynamicObj[]),
    };
  },
});
</script>

